package com.rikkeibank.account.service; import com.rikkeibank.account.dto.AccountTypeRequest; import com.rikkeibank.account.model.AccountType; import com.rikkeibank.account.repository.AccountTypeRepository; import java.util.*; import org.springframework.cache.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class AccountTypeService{private final AccountTypeRepository repo;public AccountTypeService(AccountTypeRepository r){repo=r;}@Cacheable(value="account_types",key="#id") public AccountType find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy loại tài khoản"));}@Cacheable("account_type_list") public List<AccountType> all(){return repo.findAll();}@Transactional @Caching(put=@CachePut(value="account_types",key="#result.id"),evict=@CacheEvict(value="account_type_list",allEntries=true)) public AccountType create(AccountTypeRequest r){AccountType a=new AccountType();apply(a,r);return repo.save(a);}@Transactional @Caching(put=@CachePut(value="account_types",key="#id"),evict=@CacheEvict(value="account_type_list",allEntries=true)) public AccountType update(Long id,AccountTypeRequest r){AccountType a=find(id);apply(a,r);return repo.save(a);}@Transactional @Caching(evict={@CacheEvict(value="account_types",key="#id"),@CacheEvict(value="account_type_list",allEntries=true)}) public void delete(Long id){repo.delete(find(id));}private void apply(AccountType a,AccountTypeRequest r){a.setCode(r.code());a.setName(r.name());a.setDescription(r.description());}}
